INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt einen neuen Mitarbeiter hinzu? "INSERT INTO employees (id, name, salary) VALUES (1, ''Anna'', 50000)"', 2, '[{"text": "INSERT", "correct": true, "because": "Fügt neuen Datensatz ein"}, {"text": "UPDATE", "correct": false, "because": "Ändert bestehende Daten"}, {"text": "SELECT", "correct": false, "because": "Fragt Daten ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "UPDATE products SET price = 29.99 WHERE prod_id = 101"?', 3, '[{"text": "Setzt Preis von prod_id 101 auf 29.99", "correct": true, "because": "Gezielte Änderung"}, {"text": "Fügt neuen Datensatz ein", "correct": false, "because": "Kein INSERT"}, {"text": "Löscht prod_id 101", "correct": false, "because": "Kein DELETE"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl entfernt alle Bestellungen vor 2023? "DELETE FROM orders WHERE order_date < ''2023-01-01''"?', 4, '[{"text": "DELETE", "correct": true, "because": "Löscht gefilterte Daten"}, {"text": "UPDATE", "correct": false, "because": "Ändert nur"}, {"text": "TRUNCATE", "correct": false, "because": "Löscht alles ohne Filter"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "INSERT INTO customers (cust_id, name) VALUES (1001, ''Max'')" in einer leeren Tabelle?', 2, '[{"text": "Fügt Max als Kunden hinzu", "correct": true, "because": "Erster Datensatz"}, {"text": "Ändert bestehenden Kunden", "correct": false, "because": "Kein UPDATE"}, {"text": "Löscht Tabelle", "correct": false, "because": "Kein DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erhöht "salary" um 10% für "dept_id = 5"? "UPDATE employees SET salary = salary * 1.1 WHERE dept_id = 5"?', 5, '[{"text": "UPDATE", "correct": true, "because": "Ändert Daten mit Berechnung"}, {"text": "INSERT", "correct": false, "because": "Fügt hinzu"}, {"text": "DELETE", "correct": false, "because": "Löscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "DELETE FROM tasks WHERE priority = ''low'' AND status = ''done''"?', 3, '[{"text": "Löscht erledigte Aufgaben mit niedriger Priorität", "correct": true, "because": "Mehrere Bedingungen"}, {"text": "Ändert Status auf done", "correct": false, "because": "Kein UPDATE"}, {"text": "Fügt Aufgaben hinzu", "correct": false, "because": "Kein INSERT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt zwei Produkte hinzu? "INSERT INTO products (id, name, price) VALUES (1, ''Pen'', 1.99), (2, ''Book'', 9.99)"?', 4, '[{"text": "INSERT", "correct": true, "because": "Mehrfacheinfügung möglich"}, {"text": "UPDATE", "correct": false, "because": "Ändert nur"}, {"text": "SELECT", "correct": false, "because": "Fragt ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "UPDATE orders SET shipped = ''yes'' WHERE total > 1000"?', 2, '[{"text": "Markiert Bestellungen über 1000 als versandt", "correct": true, "because": "Gezielte Änderung"}, {"text": "Löscht Bestellungen über 1000", "correct": false, "because": "Kein DELETE"}, {"text": "Fügt shipped-Spalte hinzu", "correct": false, "because": "Kein DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl löscht Kunden ohne Email? "DELETE FROM customers WHERE email IS NULL"?', 3, '[{"text": "DELETE", "correct": true, "because": "Löscht gefilterte Daten"}, {"text": "UPDATE", "correct": false, "because": "Ändert nur"}, {"text": "DROP", "correct": false, "because": "Löscht Tabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "INSERT INTO sales (sale_id, amount) SELECT id, total FROM orders WHERE total > 500"?', 5, '[{"text": "Kopiert Bestellungen über 500 in sales", "correct": true, "because": "INSERT mit SELECT"}, {"text": "Ändert orders", "correct": false, "because": "Nur Abfrage"}, {"text": "Löscht sales", "correct": false, "because": "Kein DELETE"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl setzt "stock" auf 0 für "price < 10"? "UPDATE inventory SET stock = 0 WHERE price < 10"?', 2, '[{"text": "UPDATE", "correct": true, "because": "Ändert gefilterte Daten"}, {"text": "INSERT", "correct": false, "because": "Fügt hinzu"}, {"text": "DELETE", "correct": false, "because": "Löscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "DELETE FROM employees WHERE hire_date < ''2020-01-01'' OR status = ''inactive''"?', 4, '[{"text": "Löscht alte oder inaktive Mitarbeiter", "correct": true, "because": "Logische OR-Bedingung"}, {"text": "Ändert hire_date", "correct": false, "because": "Kein UPDATE"}, {"text": "Fügt Mitarbeiter ein", "correct": false, "because": "Kein INSERT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt einen Datensatz ohne Spaltenangabe ein? "INSERT INTO dept VALUES (1, ''HR'')" in "CREATE TABLE dept (id INT, name VARCHAR(50))"?', 3, '[{"text": "INSERT", "correct": true, "because": "Werte in Reihenfolge"}, {"text": "UPDATE", "correct": false, "because": "Ändert Daten"}, {"text": "SELECT", "correct": false, "because": "Fragt ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "UPDATE tasks SET priority = ''high'' WHERE due_date = ''2023-12-01''"?', 2, '[{"text": "Setzt Priorität für Fälligkeit 2023-12-01 auf high", "correct": true, "because": "Gezielte Änderung"}, {"text": "Löscht Aufgaben vom 2023-12-01", "correct": false, "because": "Kein DELETE"}, {"text": "Fügt due_date hinzu", "correct": false, "because": "Kein DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl löscht Bestellungen über 1000? "DELETE FROM orders WHERE total > 1000"?', 3, '[{"text": "DELETE", "correct": true, "because": "Löscht gefilterte Daten"}, {"text": "UPDATE", "correct": false, "because": "Ändert nur"}, {"text": "TRUNCATE", "correct": false, "because": "Löscht alles"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "INSERT INTO users (id, name, email) VALUES (2, ''Ben'', ''ben@example.com'')" wenn id eindeutig ist?', 4, '[{"text": "Fügt Ben hinzu, wenn id 2 frei ist", "correct": true, "because": "Eindeutigkeit geprüft"}, {"text": "Ändert id 2", "correct": false, "because": "Kein UPDATE"}, {"text": "Fehler bei Duplikat", "correct": false, "because": "Abhängig von Constraint"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl verdoppelt "price" für "category = ''tech''"? "UPDATE products SET price = price * 2 WHERE category = ''tech''"?', 5, '[{"text": "UPDATE", "correct": true, "because": "Ändert mit Berechnung"}, {"text": "INSERT", "correct": false, "because": "Fügt hinzu"}, {"text": "DELETE", "correct": false, "because": "Löscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "DELETE FROM sales WHERE amount < 50 AND sale_date < ''2023-01-01''"?', 3, '[{"text": "Löscht alte Verkäufe unter 50", "correct": true, "because": "Mehrere Bedingungen"}, {"text": "Ändert amount", "correct": false, "because": "Kein UPDATE"}, {"text": "Fügt Verkäufe hinzu", "correct": false, "because": "Kein INSERT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt Daten aus "temp_users" ein? "INSERT INTO users (id, name) SELECT user_id, username FROM temp_users WHERE active = 1"?', 4, '[{"text": "INSERT", "correct": true, "because": "Kombiniert mit SELECT"}, {"text": "UPDATE", "correct": false, "because": "Ändert nur"}, {"text": "DELETE", "correct": false, "because": "Löscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "UPDATE dept SET budget = budget + 1000 WHERE id IN (1, 2)"?', 2, '[{"text": "Erhöht Budget für id 1 und 2 um 1000", "correct": true, "because": "IN filtert mehrere Werte"}, {"text": "Löscht id 1 und 2", "correct": false, "because": "Kein DELETE"}, {"text": "Fügt Budget-Spalte hinzu", "correct": false, "because": "Kein DDL"}]');
